import {t,machine,zoneName} from './i18n.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function openWorkoutEditor({gym,equipment,steps,meta,onSave}){const dialog=document.querySelector('#workout-editor');let draft=steps.map(s=>({...s})),details={name:meta?.name||t('custom'),goal:meta?.goal||'general',notes:meta?.notes||''},search='',zone='all',floor='all';const lookup=id=>equipment.find(e=>e.id===id);const labelFloor=e=>t(e.floor?'first':'ground');
function show(){dialog.innerHTML=`<form id="editor-form"><div class="editor-header"><div><div class="eyebrow">${esc(gym.name)} · ${t('yourTraining')}</div><h2 id="editor-title">${t('editorTitle')}</h2><p>${t('editorSubtitle',{gym:esc(gym.name)})}</p></div><button type="button" class="editor-close" id="editor-close" aria-label="${t('close')}">×</button></div><div class="editor-meta"><label>${t('workoutName')}<input id="draft-name" required maxlength="60" value="${esc(details.name)}" placeholder="${t('workoutNamePlaceholder')}"></label><label>${t('workoutGoal')}<select id="draft-goal">${['general','muscle','strengthGoal','endurance','mobility'].map(g=>`<option value="${g}" ${details.goal===g?'selected':''}>${t(g)}</option>`).join('')}</select></label><label class="editor-notes">${t('workoutNotes')}<input id="draft-notes" maxlength="300" value="${esc(details.notes)}" placeholder="${t('workoutNotesPlaceholder')}"></label></div><div class="editor-columns"><section class="editor-workout"><div class="editor-section-heading"><h3>${t('workoutExercises')}</h3><span id="draft-summary"></span></div><div id="draft-exercises"></div></section><section class="editor-library"><div class="editor-section-heading"><h3>${t('availableHere')}</h3><span>${equipment.length}</span></div><p class="editor-library-note">${t('onlyThisGym')}</p><input id="editor-search" type="search" placeholder="${t('search')}" aria-label="${t('search')}" value="${esc(search)}"><div class="editor-filters"><select id="editor-zone" aria-label="${t('catalog')}">${['all','Cardio','Siła','Wolne ciężary','Funkcjonalna'].map(z=>`<option value="${z}" ${zone===z?'selected':''}>${z==='all'?t('all'):zoneName(z)}</option>`).join('')}</select>${gym.floors>1?`<select id="editor-floor" aria-label="${t('floorLabel')}"><option value="all">${t('allFloors')}</option><option value="0">${t('ground')}</option><option value="1">${t('first')}</option></select>`:''}</div><div id="editor-equipment"></div></section></div><div class="editor-footer"><span id="editor-error" role="alert"></span><button type="button" class="secondary" id="editor-cancel">${t('cancel')}</button><button type="submit" class="primary" id="editor-save">${t('saveWorkout')} →</button></div></form>`;
const $=s=>dialog.querySelector(s);$('#draft-name').oninput=e=>details.name=e.target.value;$('#draft-goal').onchange=e=>details.goal=e.target.value;$('#draft-notes').oninput=e=>details.notes=e.target.value;$('#editor-search').oninput=e=>{search=e.target.value;renderLibrary()};$('#editor-zone').onchange=e=>{zone=e.target.value;renderLibrary()};if($('#editor-floor')){$('#editor-floor').value=floor;$('#editor-floor').onchange=e=>{floor=e.target.value;renderLibrary()}}$('#editor-close').onclick=$('#editor-cancel').onclick=()=>dialog.close();$('#editor-form').onsubmit=event=>{event.preventDefault();const invalid=draft.some(s=>!Number.isInteger(Number(s.sets))||+s.sets<1||+s.sets>10||!String(s.reps).trim()||!Number.isFinite(+s.rest)||+s.rest<0||+s.rest>600||(s.weight!==''&&(!Number.isFinite(+s.weight)||+s.weight<0||+s.weight>1000)));const error=!details.name.trim()?t('noName'):!draft.length?t('noExercises'):invalid?t('invalidWorkout'):'';if(error){$('#editor-error').textContent=error;return}onSave(draft.map(s=>({...s,sets:+s.sets,rest:Math.round(+s.rest),reps:String(s.reps).trim()})),{...details,name:details.name.trim()});dialog.close()};renderDraft();renderLibrary()}
function renderDraft(){const list=dialog.querySelector('#draft-exercises');list.innerHTML=draft.length?draft.map((s,i)=>{const e=machine(lookup(s.id));return `<article class="draft-card"><div class="draft-card-heading"><span class="step-num">${i+1}</span><div><strong>${e.name}</strong><small>${zoneName(e.zone)} · ${labelFloor(e)}</small></div><div class="reorder"><button type="button" data-reorder="${i}:-1" aria-label="${esc(t('moveUp',{name:e.name}))}" ${i===0?'disabled':''}>↑</button><button type="button" data-reorder="${i}:1" aria-label="${esc(t('moveDown',{name:e.name}))}" ${i===draft.length-1?'disabled':''}>↓</button><button type="button" data-delete="${i}" aria-label="${esc(t('remove',{name:e.name}))}">×</button></div></div><div class="draft-fields"><label>${t('sets')}<input required type="number" min="1" max="10" step="1" data-index="${i}" data-field="sets" value="${esc(s.sets)}"></label><label>${t('reps')}<input required maxlength="20" data-index="${i}" data-field="reps" value="${esc(s.reps)}"></label><label>${t('restSeconds')}<input required type="number" min="0" max="600" step="1" data-index="${i}" data-field="rest" value="${esc(s.rest)}"></label><label>${t('weight')}<input type="number" min="0" max="1000" step="any" data-index="${i}" data-field="weight" value="${esc(s.weight||'')}" placeholder="—"></label></div><label class="draft-note-label">${t('exerciseNote')}<input maxlength="200" data-index="${i}" data-field="note" value="${esc(s.note||'')}" placeholder="${t('optional')}"></label></article>`}).join(''):`<div class="editor-empty"><span>＋</span><p>${t('editorEmpty')}</p></div>`;list.querySelectorAll('[data-field]').forEach(input=>input.oninput=e=>{draft[+e.target.dataset.index][e.target.dataset.field]=e.target.value;summary()});list.querySelectorAll('[data-reorder]').forEach(b=>b.onclick=()=>{const [i,d]=b.dataset.reorder.split(':').map(Number);[draft[i],draft[i+d]]=[draft[i+d],draft[i]];renderDraft()});list.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{draft.splice(+b.dataset.delete,1);renderDraft();renderLibrary()});summary()}
function summary(){dialog.querySelector('#draft-summary').textContent=t('editorSummary',{n:draft.length,sets:draft.reduce((sum,s)=>sum+(+s.sets||0),0)})}
function renderLibrary(){const results=equipment.filter(e=>(floor==='all'||e.floor===+floor)&&(zone==='all'||e.zone===zone)&&[e.name,e.short,machine(e).name,machine(e).area].join(' ').toLowerCase().includes(search.toLowerCase()));dialog.querySelector('#editor-equipment').innerHTML=results.length?results.map(r=>{const e=machine(r),added=draft.some(s=>s.id===e.id);return `<button type="button" class="editor-equipment-card ${added?'added':''}" data-add="${e.id}" ${added?'disabled':''}><span class="catalog-number">${String(e.number).padStart(2,'0')}</span><span><strong>${e.name}</strong><small>${zoneName(e.zone)} · ${labelFloor(e)}</small></span><span class="editor-add-label">${added?'✓':'+ '+t('addExercise')}</span></button>`}).join(''):`<p class="empty">${t('noResults')}</p>`;dialog.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const e=lookup(b.dataset.add);draft.push({id:e.id,sets:e.sets,reps:e.reps,rest:e.rest,weight:'',note:''});renderDraft();renderLibrary()})}
show();if(!dialog.open)dialog.showModal();dialog.querySelector('#draft-name').focus();}
